    32→function formatDate(dateString: string): string {
    33→  const date = new Date(dateString);
    34→  return date.toLocaleDateString('en-US', {
    35→    month: 'short',
    36→    day: 'numeric',
    37→    year: 'numeric',
    38→  });
    39→}
    40→
    41→function formatRelativeDate(dateString: string | null): string {
    42→  if (!dateString) return 'Never';
    43→  const date = new Date(dateString);
    44→  const now = new Date();
    45→  const diffMs = now.getTime() - date.getTime();
    46→  const diffMins = Math.floor(diffMs / 60000);
    47→  const diffHours = Math.floor(diffMs / 3600000);
    48→  const diffDays = Math.floor(diffMs / 86400000);
    49→
    50→  if (diffMins < 1) return 'Just now';
    51→  if (diffMins < 60) return `${diffMins}m ago`;
    52→  if (diffHours < 24) return `${diffHours}h ago`;
    53→  if (diffDays < 7) return `${diffDays}d ago`;
    54→  return formatDate(dateString);
    55→}
